<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Bursar'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$categories=['Utilities','Repairs and maintenance','Learning materials','Transport','Food and boarding','Examinations','Administration','Communication','Security','Other'];
$category=(string)($_POST['category']??'');$supplier=trim((string)($_POST['supplier']??''));$description=trim((string)($_POST['description']??''));$reference=trim((string)($_POST['invoice_reference']??''));$amount=$_POST['amount']??null;$currency=(string)($_POST['currency']??'');$date=trim((string)($_POST['expense_date']??''));
if(!in_array($category,$categories,true)||$supplier===''||strlen($supplier)>180||$description===''||strlen($description)>500||strlen($reference)>100||!is_numeric($amount)||(float)$amount<=0||(float)$amount>999999999999.99||!in_array($currency,['USD','ZiG'],true)||!expense_valid_date($date)||$date>date('Y-m-d')){$_SESSION['error']='Check the expense details and try again.';header('Location: ../?page=expenses');exit;}
try{$pdo=db();$stmt=$pdo->prepare("INSERT INTO school_expenses (category,supplier,description,invoice_reference,amount,currency,expense_date,created_by) VALUES (:category,:supplier,:description,:reference,:amount,:currency,:date,:user)");$stmt->execute(['category'=>$category,'supplier'=>$supplier,'description'=>$description,'reference'=>$reference?:null,'amount'=>number_format((float)$amount,2,'.',''),'currency'=>$currency,'date'=>$date,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();audit_log('expenses.submitted','school_expenses',$id,['category'=>$category,'currency'=>$currency,'amount'=>number_format((float)$amount,2,'.','')]);$_SESSION['notice']='Expense submitted for approval.';}catch(Throwable $e){error_log('Expense submission failed: '.$e->getMessage());$_SESSION['error']='Could not submit the expense.';}
header('Location: ../?page=expenses');exit;
function expense_valid_date(string $date):bool{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))return false;$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);$e=DateTimeImmutable::getLastErrors();return $d!==false&&$d->format('Y-m-d')===$date&&($e===false||(!$e['warning_count']&&!$e['error_count']));}
